import{_ as t,o as a,c as s,ah as d}from"./chunks/framework.C-FRNfAJ.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/getting-started.md","filePath":"src/en/guide/getting-started.md"}'),o={name:"en/guide/getting-started.md"};function i(n,e,r,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>This page installs Kura locally and lists the day-to-day commands.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><strong>PHP 8.3+</strong> with the <code>pdo_mysql</code> (or <code>pdo_sqlite</code>), <code>mbstring</code>, <code>openssl</code>, <code>sodium</code>, <code>dom</code>, <code>xmlreader</code>, <code>fileinfo</code>, <code>zip</code> and <code>gd</code> extensions (the last two are used for PDFs and spreadsheets).</li><li><strong>Composer</strong> 2.</li><li><strong>Node.js 20.19+</strong> (see <code>.nvmrc</code>) and <strong>pnpm</strong> 9+.</li><li><strong>SQLite</strong> (bundled with PHP) for development, or MySQL to get closer to production.</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span></span></code></pre></div><p>The command installs the PHP and JS dependencies, copies <code>.env.example</code> to <code>.env</code>, generates the application key, runs the migrations, seeds the database, creates the storage link and builds the assets.</p><p>Then start the development stack:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>The application is served at <code>http://localhost:8000</code>.</p><h2 id="demo-account" tabindex="-1">Demo account <a class="header-anchor" href="#demo-account" aria-label="Permalink to &quot;Demo account&quot;">​</a></h2><p>The seeder creates an administrator account:</p><table tabindex="0"><thead><tr><th>Email</th><th>Password</th></tr></thead><tbody><tr><td><code>test@example.com</code></td><td><code>password</code></td></tr></tbody></table><p>It holds the <code>admin</code> role: you can sign in and open <code>/admin/users</code> right away. To create another administrator on a fresh instance:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users:create-admin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">emai</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;name&gt;&quot;</span></span></code></pre></div><p>The password is requested on screen, never passed as an argument.</p><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><p><code>.env.example</code> is commented line by line. The variables worth knowing:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Purpose</th><th>Local default</th></tr></thead><tbody><tr><td><code>APP_ENV</code>, <code>APP_URL</code></td><td>Environment and base URL used to generate links</td><td><code>local</code>, <code>http://localhost:8000</code></td></tr><tr><td><code>DB_CONNECTION</code></td><td><code>sqlite</code>, <code>mysql</code> or <code>pgsql</code></td><td><code>sqlite</code></td></tr><tr><td><code>MAIL_MAILER</code></td><td>Email transport</td><td><code>log</code> (writes to the logs)</td></tr><tr><td><code>QUEUE_CONNECTION</code></td><td>Queue backend</td><td><code>database</code></td></tr><tr><td><code>NEXTBOXX_SITE_API_KEY</code></td><td>Key expected by the NextBoxx website API</td><td>empty</td></tr><tr><td><code>SEVE_URL</code>, <code>SEVE_WS_TOKEN</code></td><td>Connection to the Moodle web services</td><td>empty</td></tr><tr><td><code>WHATSAPP_TOKEN</code>, <code>WHATSAPP_PHONE_NUMBER_ID</code></td><td>WhatsApp Business Cloud API</td><td>empty</td></tr></tbody></table><p>As long as the Sève and WhatsApp variables are empty, Kura works normally: changes destined for Sève stay in the queue and messages are sent by email only.</p><h2 id="useful-commands" tabindex="-1">Useful commands <a class="header-anchor" href="#useful-commands" aria-label="Permalink to &quot;Useful commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>composer dev</code></td><td>Server, queue worker, Vite and logs in parallel</td></tr><tr><td><code>composer test</code></td><td>Pint, Larastan then Pest — the CI gate</td></tr><tr><td><code>composer ci:check</code></td><td>Adds ESLint, Prettier and <code>vue-tsc</code> to the check</td></tr><tr><td><code>pnpm run build</code></td><td>Builds the production assets</td></tr><tr><td><code>php artisan migrate</code></td><td>Applies the migrations</td></tr><tr><td><code>php artisan test --compact</code></td><td>Runs the Pest suite</td></tr><tr><td><code>php artisan users:create-admin</code></td><td>Creates an administrator account</td></tr><tr><td><code>php artisan seve:client</code></td><td>Registers Sève as an OAuth client and prints its secret</td></tr></tbody></table><h2 id="first-steps-in-the-application" tabindex="-1">First steps in the application <a class="header-anchor" href="#first-steps-in-the-application" aria-label="Permalink to &quot;First steps in the application&quot;">​</a></h2><ol><li>Sign in with the demo account.</li><li>Open <strong>Administration → Users</strong> (<code>/admin/users</code>) to create the team accounts and grant roles.</li><li>Fill in the <strong>settings</strong> (<code>/admin/settings</code>): invoice legal mentions, certificate mention thresholds, profitability thresholds.</li><li>Publish a first programme in the <strong>catalogue</strong>, validate its QCM bank, then open a <strong>cohort</strong>.</li><li>Submit a candidature through the API or the interface to walk the whole journey.</li></ol><h2 id="what-next" tabindex="-1">What next <a class="header-anchor" href="#what-next" aria-label="Permalink to &quot;What next&quot;">​</a></h2><ul><li><a href="/kura-guide/en/guide/architecture.html">Architecture</a> to understand the code.</li><li><a href="/kura-guide/en/guide/development.html">Development</a> for conventions and tests.</li><li><a href="/kura-guide/en/guide/deployment.html">Deployment</a> for going to production.</li></ul>',26)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
